#include <bits/stdc++.h>
using namespace std;

static int countA, countB, total, maxTransport;
static const long long MOD = 1000000007;
static long long nCr[100][100];
static unordered_map<int, pair<int, long long>> stateMap;
static queue<int> queueStates;

struct Pair {
    int depth;
    long long ways;
    Pair(int d, long long w) : depth(d), ways(w) {}
};

void processState(int state);
void updateState(int i, int j, int side, int prevState, long long edgeWays);
void initChoose();

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total >> maxTransport;
    countA = 0;
    countB = 0;
    for (int i = 0; i < total; i++) {
        int val;
        cin >> val;
        if (val == 50) countA++;
        else countB++;
    }
    initChoose();
    int initialState = 1000000 + 100 * countA + countB;
    queueStates.push(initialState);
    stateMap[initialState] = {0, 1};
    while (!queueStates.empty()) {
        processState(queueStates.front());
        queueStates.pop();
    }
    if (stateMap.count(0))
        cout << stateMap[0].first << "\n" << stateMap[0].second << "\n";
    else
        cout << -1 << "\n" << 0 << "\n";
    return 0;
}

void processState(int state) {
    int side = state / 1000000;
    int aCurr = (state % 1000000) / 100;
    int bCurr = state % 100;
    if (side > 0) {
        for (int i = aCurr; i >= 0 && 50 * (aCurr - i) <= maxTransport; i--) {
            for (int j = bCurr; j >= 0 && 50 * (aCurr - i) + 100 * (bCurr - j) <= maxTransport; j--) {
                if (i != aCurr || j != bCurr)
                    updateState(i, j, side, state, (nCr[aCurr][i] * nCr[bCurr][j]) % MOD);
            }
        }
    } else {
        for (int i = aCurr; i <= countA && 50 * (i - aCurr) <= maxTransport; i++) {
            for (int j = bCurr; j <= countB && 50 * (i - aCurr) + 100 * (j - bCurr) <= maxTransport; j++) {
                if (i != aCurr || j != bCurr)
                    updateState(i, j, side, state, (nCr[countA - aCurr][i - aCurr] * nCr[countB - bCurr][j - bCurr]) % MOD);
            }
        }
    }
}

void updateState(int i, int j, int side, int prevState, long long edgeWays) {
    int newState = 1000000 * (1 - side) + i * 100 + j;
    int newDepth = stateMap[prevState].first + 1;
    if (!stateMap.count(newState)) {
        stateMap[newState] = {newDepth, 0};
        queueStates.push(newState);
    }
    if (stateMap[newState].first == newDepth)
        stateMap[newState].second = (stateMap[newState].second + stateMap[prevState].second * edgeWays % MOD) % MOD;
}

void initChoose() {
    for (int i = 0; i < 100; i++) nCr[i][0] = 1;
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= i; j++) {
            nCr[i][j] = (nCr[i - 1][j - 1] + nCr[i - 1][j]) % MOD;
        }
    }
}

